const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Mount Vesuvius location (approximately 40.82°N, 14.43°E)
  const vesuvius = ee.Geometry.Point([14.4266, 40.8214]);
  const roi = vesuvius.buffer(2000); // 2km buffer around summit

  // Date range for January 2, 2022
  const startDate = '2022-01-02';
  const endDate = '2022-01-03';

  // Landsat 8 Collection 2 Level 2
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(vesuvius)
    .filterDate(startDate, endDate);

  const colSize = await collection.size().getInfo();
  console.log(`Landsat 8 images found: ${colSize}`);

  if (colSize === 0) {
    // Try expanding date range slightly
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(vesuvius)
      .filterDate('2022-01-01', '2022-01-04');

    const colSize2 = await collection.size().getInfo();
    console.log(`Expanded search (Jan 1-3): ${colSize2} images`);

    if (colSize2 === 0) {
      console.log('No Landsat 8 images available for this date/location.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get the image
  const image = collection.first();

  // Check cloud cover using QA_PIXEL band
  const qaPixel = image.select('QA_PIXEL');

  // Bit 3 is cloud, bit 4 is cloud shadow
  const cloudBit = 1 << 3;
  const cloudShadowBit = 1 << 4;

  const clouds = qaPixel.bitwiseAnd(cloudBit).neq(0);
  const cloudShadow = qaPixel.bitwiseAnd(cloudShadowBit).neq(0);
  const cloudMask = clouds.or(cloudShadow);

  // Calculate cloud percentage over Vesuvius
  const stats = await cloudMask.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  const cloudPercent = (stats.QA_PIXEL || 0) * 100;
  console.log(`Cloud coverage over Vesuvius: ${cloudPercent.toFixed(1)}%`);

  // Also check pixel count
  const pixelCount = await image.select('SR_B4').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).getInfo();

  console.log(`Valid pixels: ${pixelCount.SR_B4 || 0}`);

  if (pixelCount.SR_B4 === 0) {
    console.log('No valid pixels in region.');
    console.log('<answer>C2</answer>');
    return;
  }

  // If cloud coverage is low (<30%), the cone was visible
  if (cloudPercent < 30) {
    console.log('Vesuvius cone was visible (low cloud cover).');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vesuvius cone was NOT visible (obscured by clouds).');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
